import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse('{"title":"TypeScript Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"TypeScript","tag":"TypeScript","title":"TypeScript Tag","prev":null,"next":null,"posts":[{"title":"如何使用TypeScript进行后端开发","url":"/posts/2022-10-29-typescript-backend/","date":"2022-10-29 11:47","tags":["TypeScript"],"html":"<p>我们经常使用 TypeScript 进行开发，webpack 会自动帮我们编译成浏览器可以执行的 JS 文件。相关的开发工具也很完善，但是进行后端开发的资料就比较少了，我们来讲解下如何使用 TypeScript 进行后端开发。</p>\\n<h2 id=\\"开发环境自动重新加载\\" tabindex=\\"-1\\">开发环境自动重新加载 <a class=\\"header-anchor\\" href=\\"#开发环境自动重新加载\\" aria-label=\\"Permalink to &quot;开发环境自动重新加载&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端有 <a href=\\"https://webpack.js.org/concepts/hot-module-replacement/\\" target=\\"_blank\\" rel=\\"noreferrer\\">HMR</a> 技术可以实在自动热加载。后端实现这个功能其实也很简单。 首先需要按照 <code>nodemon</code> 和 <code>ts-node</code>。\\n我们使用 pnpm 进行包管理。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> nodemon</span><span style=\\"color:#032F62\\"> ts-node</span><span style=\\"color:#005CC5\\"> -D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后在 <code>package.json</code> 添加命令。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">nodemon</span><span style=\\"color:#032F62\\"> src/index.ts</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p><code>nodemon</code> 可以完成对文件的监控并且自动 reload，<code>ts-node</code> 完成对 TypeScript 的支持。并且不需要配置，<code>nodemon</code> 会自动调用 <code>ts-node</code>。</p>\\n<h2 id=\\"支持绝对路径引用\\" tabindex=\\"-1\\">支持绝对路径引用 <a class=\\"header-anchor\\" href=\\"#支持绝对路径引用\\" aria-label=\\"Permalink to &quot;支持绝对路径引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端开发中也经常使用绝对路径，所以希望后端也能使用绝对路径。TypeScript 默认不支持绝对路径的使用，我们需要引用第三方来完成这个操作。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> ttypescript</span><span style=\\"color:#032F62\\"> typescript-transform-paths</span><span style=\\"color:#005CC5\\"> -D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>ttypescript 支持在 build 过程中添加插件来完成很多功能，绝对路径转换成相对路径就是其中一个功能， typescript-transform-paths 这个插件就是用来完成绝对路径映射的。我们需要在 <code>tsconfig.json</code> 中进行相关的配置。</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"ts-node\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"transpileOnly\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"require\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"typescript-transform-paths/register\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"compilerOptions\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"target\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"ESNext\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"module\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"commonjs\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"moduleResolution\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"Node\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"outDir\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"dist\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"resolveJsonModule\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"skipLibCheck\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"experimentalDecorators\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"emitDecoratorMetadata\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"esModuleInterop\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"allowSyntheticDefaultImports\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"baseUrl\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\".\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"paths\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">      \\"@/*\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"src/*\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"plugins\\"</span><span style=\\"color:#24292E\\">: [{ </span><span style=\\"color:#005CC5\\">\\"transform\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"typescript-transform-paths\\"</span><span style=\\"color:#24292E\\"> }]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"include\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"src\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br></div></div><p>首先在 <code>paths</code> 字段下，映射文件夹路径，这样就可以使用 <code>@/posts/index.ts</code> 这种格式来引用模块。当然路径映射在开发环境下需要 <code>ts-node</code> 的支持，我们在 <code>ts-node</code> 的 <code>require</code> 字段上引用我们安装的插件。最后是编译成 JS 文件的过程中添加绝对路径的支持。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">ttsc</span><span style=\\"color:#005CC5\\"> -p</span><span style=\\"color:#032F62\\"> tsconfig.json</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>使用增强版 <code>ttsc</code> 来完成路径的转换，可以看到生成的 JS 文件中已经是正常的相对路径引用了，前端的时候大多数都是 webpack 完成打包的，后端的话可以直接使用 <code>ttsc</code> 来完成编译过程。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>TypeScript 在类型定义上的支持可以让我们很方便开发大型项目，后端支持了 reload 和绝对路径之后开发效率也可以大大提高。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://chaika.hatenablog.com/entry/2021/12/20/083000\\" target=\\"_blank\\" rel=\\"noreferrer\\">ts-node で path alias が効かないにハマる</a></p>\\n<p><a href=\\"https://github.com/acgotaku/mapdoge-bot\\" target=\\"_blank\\" rel=\\"noreferrer\\">mapdoge-bot</a></p>\\n"}]},"relativePath":"tags/TypeScript/index.md","filePath":"tags/[slug].md"}'),e={name:"tags/TypeScript/index.md"};function p(l,o,r,t,c,i){return n(),a("div")}const b=s(e,[["render",p]]);export{y as __pageData,b as default};
